_UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
_UNIT_ORDER = {"d": 3, "h": 2, "m": 1, "s": 0}


def parse_duration(text: str) -> int:
    """Parse a duration string such as ``90s`` or ``1h30m`` into seconds."""
    if not text:
        raise ValueError(f"invalid duration: {text!r}")

    total = 0
    i = 0
    n = len(text)
    last_order = 4  # higher than any valid unit order
    seen = set()

    while i < n:
        # Parse integer part
        j = i
        while j < n and text[j].isdigit():
            j += 1
        if j == i:
            raise ValueError(f"invalid duration: {text!r}")
        number = int(text[i:j])

        # Parse unit
        if j >= n:
            raise ValueError(f"invalid duration: {text!r}")
        unit = text[j]
        if unit not in _UNITS:
            raise ValueError(f"invalid duration: {text!r}")

        # Check uniqueness and descending order
        if unit in seen:
            raise ValueError(f"invalid duration: {text!r}")
        order = _UNIT_ORDER[unit]
        if order >= last_order:
            raise ValueError(f"invalid duration: {text!r}")

        total += number * _UNITS[unit]
        seen.add(unit)
        last_order = order
        i = j + 1

    return total
